module TopModule (
    input clk,
    input reset,
    output reg ena [3:0],
    output reg q [15:0]
);

    reg [3:0] digit_ena = 4'b0000;
    reg [15:0] digit_q = 16'b0000000000000000;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            digit_ena <= 4'b0000;
            digit_q <= 16'b0000000000000000;
        end else begin
            if (digit_ena[0]) begin
                digit_q[15] <= digit_q[15] + 1'b1;
                digit_ena[0] <= 4'b0000;
            end
            if (digit_ena[1]) begin
                digit_q[14] <= digit_q[14] + 1'b1;
                digit_ena[1] <= 4'b0000;
            end
            if (digit_ena[2]) begin
                digit_q[13] <= digit_q[13] + 1'b1;
                digit_ena[2] <= 4'b0000;
            end
            if (digit_ena[3]) begin
                digit_q[12] <= digit_q[12] + 1'b1;
                digit_ena[3] <= 4'b0000;
            end
            digit_ena <= ena;
            digit_q <= q;
        end
    end

    assign ena = { digit_ena };

endmodule

