module TopModule (
    input [255:0] in,
    output [7:0]  out
);

// Local parameters for bit manipulation
parameter BITS = 8;  // Number of bits in the input and output vectors
parameter BIT_MASK = 1'b1;  // Bit mask for the entire input and output vectors
parameter BIT_SET = 1'b1;  // Bit set value for the population count
parameter BIT_CLEAR = 1'b0;  // Bit clear value for the population count

// Local variable to hold the current population count
reg [BITS-1:0] pop_count;

// Population count logic
always @(posedge in) begin
    pop_count = 0;
    for (int i = 0; i < BITS; i++) begin
        pop_count += (in[i] == BIT_SET) ? BIT_SET : BIT_CLEAR;
    end
end

// Output the result
assign out = pop_count;

endmodule

