    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            for (integer i = 0; i <= 15; i = i + 1) begin
                d_reg[i] <= 16'b0;
            end
        end else begin
            for (integer i = 0; i <= 15; i = i + 1) begin
                if (byteena[i] == 1) begin
                    d_reg[i] <= d;
                end else begin
                    d_reg[i] <= d_reg[i];
                end
            end
        end
    end

    // Output the current value of each DFF
    assign q = d_reg;

endmodule

