    if (areset) begin
        data_in <= 8'b0;
        data_out <= 8'b0;
        q_reg <= 8'b0;
    end else begin
        data_in <= d;
        if (data_in == 8'b0) begin
            data_out <= 8'b0;
        end else begin
            data_out <= data_in;
            q_reg[data_in] <= 1'b1;
