module TopModule(
    input clk,
    input w,
    input R,
    input E,
    input L,
    output Q
);

reg [7:0] shift_register;
reg [7:0] load_value;

always @(posedge clk) begin
    if (E) begin
        // Enable shift
        if (R) begin
            // Load value
            load_value <= w;
            // Start shift
            shift_register <= load_value;
        end else begin
            // Perform shift
            shift_register <= {Q, shift_register[6:0]};
        end
    end else begin
        // Disable shift
        Q <= shift_register[7];
    end
end

endmodule

