    input in  [7:0],
    output anyedge [7:0]
);

    always @(posedge clk) begin
        for (int i = 0; i < 8; i++) begin
            // Detect any edge for each bit
            if (in[i] != prev_in[i] && in[i] != 1'b0) begin
                anyedge[i] = 1'b1;
            end else begin
                anyedge[i] = 1'b0;
            end

            // Update prev_in for the next iteration
            prev_in[i] = in[i];
        end
    end

