module TopModule (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

// Declare internal logic to track the previous state of the input bits
reg [7:0] prev_in;
reg [7:0] edge_flag;

// Logic to detect any edge change in the input signal
always @(posedge clk) begin
    // Update the previous state of the input bits
    prev_in <= in;

    // Check for any edge change
    if ((prev_in ^ in) == 0) begin
        // If no edge change occurred, set edge_flag to 0
        edge_flag <= 0;
    end else begin
        // If an edge change occurred, set edge_flag to 1
        edge_flag <= 1;
    end
end

// Assign the edge_flag to anyedge
assign anyedge = edge_flag;

endmodule

