module TopModule (
    input wire clk,
    input wire reset,
    output reg ena [2:0],
    output reg q [15:0]
);

    // 4-digit BCD counter
    reg [3:0] ones;
    reg [3:0] tens;
    reg [3:0] hundreds;
    reg [1:0] tens_enable;

    // Logic to generate BCD counter
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ones <= 4'b0000;
            tens <= 4'b0000;
            hundreds <= 4'b0000;
            tens_enable <= 2'b00;
        end else begin
            if (ena[2]) tens_enable <= 2'b01; // Increment tens if ena[2] is 1
            if (ena[1]) tens <= tens + 1; // Increment tens
            if (ena[0]) hundreds <= hundreds + 1; // Increment hundreds

            // Update ones if tens equals 9
            if (tens == 4'b1001) tens_enable <= 2'b11; // Increment tens if tens equals 9
            if (tens == 4'b0100) tens <= 4'b0000; // Reset tens if tens equals 9
            if (tens == 4'b0010) tens <= 4'b0000; // Reset tens if tens equals 9
            if (tens == 4'b0001) tens <= 4'b0000; // Reset tens if tens equals 9

            // Assign outputs
            ones <= tens[3:0];
            tens <= tens[7:4];
            hundreds <= tens[11:8];
            tens_enable <= tens_enable[0];
        end
    end

endmodule

