            out_always <= 1'b0;
        end else begin
            if (sel_b1 && sel_b2) begin
                out_assign <= b;
                out_always <= b;
            end else begin
                out_assign <= a;
                out_always <= a;
            end
        end
    end

    // Procedural if statement implementation
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            out_assign <= 1'b0;
            out_always <= 1'b0;
        end else begin
            if (sel_b1 && sel_b2) begin
                out_assign <= b;
                out_always <= b;
            end else begin
                out_assign <= a;
                out_always <= a;
            end
        end
    end

endmodule

