module TopModule(
    input wire a,
    input wire b,
    input wire cin,
    output reg cout,
    output reg sum
);

    // Declare the full adder components
    full_adder full_adder_inst(
        .a(a),
        .b(b),
        .cin(cin),
        .cout(cout),
        .sum(sum)
    );

endmodule

module full_adder(
    input wire a,
    input wire b,
    input wire cin,
    output reg cout,
    output reg sum
);

    // Declare the three-bit adder components
    reg [2:0] adder_output;

    // Add the three bits and handle carry-in
    adder a0(a, b, cin, adder_output[2]);
    adder a1(adder_output[2], cin, adder_output[1]);
    adder a2(adder_output[1], cin, adder_output[0]);

    // Calculate the sum
    assign sum = adder_output[0] ^ cin ^ adder_output[1];

    // Calculate the carry-out
    assign cout = (adder_output[0] & adder_output[1]) | (adder_output[1] & cin) | (adder_output[0] & cin);

endmodule

module adder(
    input wire a,
    input wire b,
    input wire cin,
    output reg sum
);

    // Declare the carry-in and carry-out signals
    reg cin_i = cin;
    reg carry_out;

    // Add the two bits
    reg s0 = a ^ b;

    // Calculate the carry-out from the sum and carry-in
    always @(posedge s0, posedge cin_i) begin
        if (cin_i == 1 && s0 == 1) begin
            carry_out = 1;
        end else begin
            carry_out = 0;
        end
    end

    // Calculate the sum
    assign sum = s0 ^ carry_out;

endmodule

