module TopModule (
    input clk,
    input reset,
    output reg [3:0] q
);

    // Variables to hold the current and next values of the decade counter
    reg [3:0] current;
    reg [3:0] next;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current <= 4'b0000; // Reset to 0
        end else begin
            current <= next; // Update current to next value
            // Decrement the current count by 1
            next <= current - 1;

            // Handle the case where the current count reaches 0 and rolls over to 9
            if (current == 4'b0000) begin
                next <= 4'b0009; // Increment to 9
            end
        end
    end

    // Assign the current value of the counter to the output port q
    assign q = current;

endmodule

