module TopModule (
    input clk,
    input reset,
    output reg ena [2:0],
    output wire q [15:0]
);

    reg [3:0] count = 0; // Initialize the counter to 0

    // Enable signals for each digit
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0; // Reset the counter when reset is high
            ena <= 0;  // Reset the enable signals
        end else if (count == 9) begin // When the counter reaches 9, increment the digits
            count <= 0;
            ena [2] <= 1; // Increment the thousands digit
        end else if (count == 99) begin
            count <= 0;
            ena [1] <= 1; // Increment the hundreds digit
        end else if (count == 999) begin
            count <= 0;
            ena [0] <= 1; // Increment the tens digit
        end else begin
            count <= count + 1; // Increment the counter by 1
        end
    end

    // Shift the counter to the right to match the BCD format
    always @(posedge clk) begin
        q [15] <= q [14];
        q [14] <= q [13];
        q [13] <= q [12];
        q [12] <= q [11];
        q [11] <= q [10];
        q [10] <= q [9];
        q [9] <= q [8];
        q [8] <= q [7];
        q [7] <= q [6];
        q [6] <= q [5];
        q [5] <= q [4];
        q [4] <= q [3];
        q [3] <= q [2];
        q [2] <= q [1];
        q [1] <= q [0];
    end

endmodule

