module TopModule (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

// Declare internal logic to track the previous state of the input bits
reg [7:0] prev_in;
reg [7:0] edge_flag;

// Logic to detect any edge for each bit in the input
always @(posedge clk) begin
    // Update the previous state of the input bits
    prev_in <= in;

    // Check if the current input bit is not equal to the previous input bit
    if (prev_in != in) begin
        // Set the edge_flag to 1 if the current input is 0 to 1 or 1 to 0 transition
        if ((prev_in == 0 && in == 1) || (prev_in == 1 && in == 0)) begin
            edge_flag <= 1;
        else begin
            edge_flag <= 0;
        end
    end else begin
        // Reset the edge_flag if the input bit remains the same
        edge_flag <= 0;
    end

    // Output the edge_flag to the anyedge output
    anyedge <= edge_flag;
end

endmodule

