module TopModule (
    input wire in,
    input wire [3:0] state,
    output reg [3:0] next_state,
    output reg out
);

    // One-hot encoding for states
    reg [3:0] state_a = 4'b0001;  // A = 4'b0001
    reg [3:0] state_b = 4'b0010;  // B = 4'b0010
    reg [3:0] state_c = 4'b0100;  // C = 4'b0100
    reg [3:0] state_d = 4'b1000;  // D = 4'b1000

    // Output logic equations
    assign out = state == state_a ? 1'b0 : state == state_b ? 1'b0 : state == state_c ? 1'b0 : state == state_d ? 1'b1 : 1'bX;

    // State transition logic
    always @(posedge in) begin
        case (state)
            state_a: begin
                next_state = state_b;
                out = 1'b0;
            end
            state_b: begin
                next_state = state_c;
                out = 1'b0;
            end
            state_c: begin
                next_state = state_a;
                out = 1'b0;
            end
            state_d: begin
                next_state = state_c;
                out = 1'b1;
            end
            default: begin
                next_state = state;
                out = 1'bX;
            end
        endcase
    end

endmodule

