module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    input  e,
    output reg [24:0] out
);

always @(posedge clk) begin
    out <= 0; // Initialize output to 0

    // Compute all 25 pairwise comparisons and store in the output vector
    for (integer i = 0; i < 25; i = i + 1) begin
        reg [1:0] pair_index = i >> 1;
        reg [1:0] pair_selector = i & 1;

        if (pair_selector == 0) begin // Even pairs
            out[i] = ~a;
            if (pair_index < 5) begin // Less than 5 pairs, no need to check further
                out[i + 1] = ~b;
                out[i + 2] = ~c;
                out[i + 3] = ~d;
                out[i + 4] = ~e;
            end else begin
                out[i + 1] = ~a;
                out[i + 2] = ~b;
                out[i + 3] = ~c;
                out[i + 4] = ~d;
            end
        end else begin // Odd pairs
            out[i] = ~e;
            if (pair_index < 5) begin // Less than 5 pairs, no need to check further
                out[i + 1] = ~d;
                out[i + 2] = ~e;
            end else begin
                out[i + 1] = ~d;
                out[i + 2] = ~e;
            end
        end
    end
end

endmodule

