module TopModule(
    input  a,
    input  b,
    input  cin,
    output cout,
    output sum
);

    // Full Adder logic
    wire cout1;
    wire cout2;

    // Sum calculation
    wire sum1;
    wire sum2;

    // Carry calculation
    wire carry1;
    wire carry2;

    // Instantiate full adder for bits a and b with carry-in cin
    full_adder #(
        .WIDTH(1)
    ) FA1 (
        .a(a),
        .b(b),
        .cin(cin),
        .cout(cout1),
        .sum(sum1)
    );

    // Instantiate full adder for bits a and carry1 with carry-in cin
    full_adder #(
        .WIDTH(1)
    ) FA2 (
        .a(a),
        .b(cout1),
        .cin(cin),
        .cout(cout2),
        .sum(sum2)
    );

    // Combine results from FA1 and FA2 to get final sum and carry-out
    always @(posedge cin or posedge a or posedge b) begin
        cout <= cout1;
        sum <= sum1;
    end

endmodule

// Full Adder module
module full_adder #(WIDTH = 1)(input a, b, cin, cout, sum);

    // Logic for full adder
    wire carry;
    wire temp_sum;

    // Perform addition with carry
    assign temp_sum = a ^ b ^ cin;

    // Calculate carry
    assign carry = a & b | b & cin | a & cin;

    // Output sum and carry
    assign cout = carry;
    assign sum = temp_sum;

endmodule

