module TopModule #(parameter RING_DURATION=10, MOTOR_DURATION=5) (
  input TopModuleInterface ifc,
  output logic [RING_DURATION-1:0] ring_counter,
  output logic [MOTOR_DURATION-1:0] motor_counter
);

  // state machine to control the ringer and motor
  logic [2:0] state;
  logic [1:0] count;

  // initial state
  initial begin
    state = 3'b000;
    count = 0;
  end

  // state transition logic
  always @(posedge ifc.ring or posedge ifc.vibrate_mode) begin
    case(state)
      3'b000: begin // initial state
        if (ifc.ring) begin
          state = 3'b001;
          count = 0;
        end else if (ifc.vibrate_mode) begin
          state = 3'b010;
          count = 0;
        end
      end
      3'b001: begin // ringing state
        ring_counter = count;
        if (count < RING_DURATION) begin
          count++;
        end else begin
          state = 3'b000;
          count = 0;
        end
      end
      3'b010: begin // vibration state
        motor_counter = count;
        if (count < MOTOR_DURATION) begin
          count++;
        end else begin
          state = 3'b000;
          count = 0;
        end
      end
      default: begin
        state = 3'b000;
        count = 0;
      end
    endcase
  end

  // outputs the appropriate state based on the current state
  assign ifc.ringer = state == 3'b001;
  assign ifc.motor = state == 3'b010;

endmodule

