        if (reset) begin
            ones <= 4'b0000;
            tens <= 4'b0000;
            hundreds <= 4'b0000;
            ena <= 3'b000;
            q <= 16'b0000000000000000;
        end else begin
            if (ena != prev_ena) begin
                if (ena[2]) ones <= ones + 1'b1;
                if (ena[1]) tens <= tens + 1'b1;
                if (ena[0]) hundreds <= hundreds + 1'b1;
                ena <= ena + 1'b1;
            end
            prev_ena <= ena;
            prev_q <= q;
