);

    // State transition logic
    always @(posedge in or posedge state) begin
        case (state)
            4'b0001: begin
                next_state = 4'b0010;
                out = 0;
            end
            4'b0010: begin
                next_state = 4'b0100;
                out = 0;
            end
            4'b0100: begin
                next_state = 4'b0001;
                out = 0;
            end
            4'b1000: begin
                next_state = 4'b0100;
                out = 1;
            end
            default: begin
                next_state = state;
                out = 0;
            end
        endcase
    end

