module TopModule (
    input  logic in,
    input  logic [3:0] state,
    output logic next_state,
    output logic out
);

    // Define the one-hot state encoding
    parameter A = 4'b0001,
               B = 4'b0010,
               C = 4'b0100,
               D = 4'b1000;

    // Implement the state transition logic
    always @(posedge in) begin
        case (state)
            A:
                next_state <= B;
            B:
                next_state <= C;
            C:
                next_state <= A;
            D:
                next_state <= C;
            default:
                next_state <= A;
        endcase
    end

    // Implement the output logic
    always @(posedge in) begin
        case (state)
            A:
                out <= 0;
            B:
                out <= 0;
            C:
                out <= 0;
            D:
                out <= 1;
            default:
                out <= 0;
        endcase
    end

