    input  wire b,
    input  wire c,
    input  wire d,
    input  wire e,
    output wire [24:0] out
);

    // Implementing the 25 pairwise one-bit comparisons
    genvar i;
    generate
        for (i = 0; i < 25; i = i + 1) begin
            always @(posedge a or posedge b or posedge c or posedge d or posedge e) begin
                if ((i % 5 == 0) && (i / 5 == a)) out[i] = 0;
                else if ((i % 5 == 1) && (i / 5 == b)) out[i] = 0;
                else if ((i % 5 == 2) && (i / 5 == c)) out[i] = 0;
                else if ((i % 5 == 3) && (i / 5 == d)) out[i] = 0;
                else if ((i % 5 == 4) && (i / 5 == e)) out[i] = 0;
                else out[i] = a ^ b ^ c ^ d ^ e; // Default comparison
            end
        end
    endgenerate

