module DFlip (
    input wire clk,
    input wire ar,
    input wire d,
    output reg q
);

    // Register to hold the previous state
    reg prev_state;

    always @(posedge clk or negedge ar) begin
        if (!ar) begin
            // Reset the flip flop to its initial state
            prev_state <= 1'b0;
            q <= 1'b0;
        end else begin
            // Update the flip flop
            prev_state <= d;
            q <= prev_state;
        end
    end

endmodule

