    if (mode == 1) begin
        // Heating mode
        heater <= !too_hot;
        aircon <= 0;
        fan <= 1;  // Always turn on the fan when heater is on
    end else if (mode == 0) begin
        // Cooling mode
        heater <= 0;
        aircon <= !too_cold;
