module TopModule(
    input wire clk,
    input wire reset,
    output reg [3:0] q,
    output reg [2:0] ena
);

// Define the 4-digit BCD counter
reg [3:0] counter = 4'b0000;
reg [2:0] digit_counter = 3'b000; // Current digit being incremented

always @(posedge clk or posedge reset) begin
    if (reset) begin
        counter <= 4'b0000;
        digit_counter <= 3'b000;
        ena <= 2'b00; // Disable all digits initially
    end else begin
        case (digit_counter)
            3'd0: begin
                counter <= counter + 1'b1;
                digit_counter <= 3'b001;
                ena <= 2'b01; // Enable the tens digit
            end
            3'd1: begin
                counter <= counter + 1'b1;
                digit_counter <= 3'b010;
                ena <= 2'b10; // Enable the ones digit
            end
            3'd2: begin
                counter <= counter + 1'b1;
                digit_counter <= 3'b100;
                ena <= 2'b11; // Enable the tens digit again
            end
            3'd3: begin
                counter <= counter + 1'b1;
                digit_counter <= 3'b100;
                ena <= 2'b11; // Enable the tens digit again
            end
            default: begin
                // If all digits are done, reset the counter
                counter <= 4'b0000;
                digit_counter <= 3'b000;
                ena <= 2'b00; // Disable all digits
            end
        endcase
    end
end

// Output q
always @(posedge clk or posedge reset) begin
    if (reset) begin
        q <= 16'b0000000000000000;
    end else begin
        q <= counter;
    end
end

endmodule

