    reg [15:0] dff [15:0];

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            // Reset all D flip-flops to 0
            for (int i = 0; i <= 15; i = i + 1) begin
                dff[i] <= 16'b0;
