module TopModule (
    input mode,
    input too_cold,
    input too_hot,
    input fan_on,
    output heater,
    output aircon,
    output fan
);

    wire heating;
    wire aircon_on;

    // State machine for heater and aircon control
    reg [1:0] state;
    reg [1:0] nextState;

    // Control logic
    always @(*) begin
        state = nextState;

        if (mode == 1) begin
            if (too_cold == 1) begin
                heating = 1'b1;
                aircon_on = 1'b0;
            end else begin
                heating = 1'b0;
                aircon_on = 1'b0;
            end
        end else begin
            if (too_hot == 1) begin
                heating = 1'b0;
                aircon_on = 1'b1;
            end else begin
                heating = 1'b0;
                aircon_on = 1'b0;
            end
        end

        if (heating || aircon_on || fan_on) begin
            nextState = 2'b11; // Both heater, aircon, and fan are on
        end else if (heating) begin
            nextState = 2'b10; // Heater is on and aircon is off
        end else if (aircon_on) begin
            nextState = 2'b01; // Aircon is on and heater is off
        end else begin
            nextState = 2'b00; // No heater, aircon, or fan is on
        end
    end

    // Fan control
    always @(posedge state) begin
        case (state)
            2'b11: fan = 1'b1; // All on
            2'b10: fan = 1'b1; // Heater on
            2'b01: fan = 1'b1; // Aircon on
            2'b00: fan = 1'b0; // None on
            default: fan = 1'b0; // Default to off
        endcase
    end

    // Connect outputs to the state machine outputs
    assign heater = state[0];
    assign aircon = state[1];
    assign fan = state[1];

endmodule

