    input too_cold,
    input too_hot,
    input fan_on,
    output heater,
    output aircon,
    output fan
);

    // Variables to keep track of the mode and the fan state
    reg [1:0] mode_reg;
    reg fan_reg;

    // Function to determine if the heater should be on
    function logic heater_on;
        if (mode_reg == 2'b01) // Heating mode
            heater_on = too_cold;
        else
            heater_on = ~too_cold;
    endfunction

    // Function to determine if the air conditioner should be on
    function logic aircon_on;
        if (mode_reg == 2'b10) // Cooling mode
            aircon_on = too_hot;
        else
            aircon_on = ~too_hot;
    endfunction

    // Assign the heater and air conditioner outputs based on the mode and fan state
    assign heater = heater_on;
    assign aircon = aircon_on;

    // Assign the fan output based on the fan_on input
    assign fan = fan_reg;

    // Update the mode register and fan state based on the mode input
    always @(posedge clk) begin
        if (rst) begin
            mode_reg = 2'b00; // Initial state is not specified, so we assume off
            fan_reg = 2'b00; // Initial state is not specified, so we assume off
        end else begin
            if (mode) begin
                if (mode_reg == 2'b00) begin
                    mode_reg = 2'b01; // Set mode to heating
                end
            end else begin
                if (mode_reg == 2'b01) begin
                    mode_reg = 2'b00; // Set mode to cooling
                end
            end
            if (fan_on) begin
                fan_reg = 2'b01; // Set fan to on
            end
        end
    end

