    reg [15:0] counter = 16'b0000000000000000; // Initial value is 0

    // Enable signal to indicate when each digit should be incremented
    reg [2:0] enable;

    // Clock and reset generation
    always @(posedge clk) begin
        if (reset) begin
            counter <= 16'b0000000000000000; // Reset counter to zero
            enable <= 3'b0;             // Reset enable signals
        end else begin
            // Increment the counter
            counter <= counter + 1;

            // Determine the enable signals based on the current counter value
            if (counter[3] == 1'b1) begin
                enable[2] <= 1'b1; // Increment the hundreds digit
            end
            if (counter[6] == 1'b1) begin
                enable[1] <= 1'b1; // Increment the tens digit
            end
            if (counter[9] == 1'b1) begin
                enable[0] <= 1'b1; // Increment the units digit
