module TopModule(
    input wire mode,
    input wire too_cold,
    input wire too_hot,
    input wire fan_on,
    output wire heater,
    output wire aircon,
    output wire fan
);

    // Constants for temperature states
    localparam LOW_TEMP = 0;
    localparam HIGH_TEMP = 1;

    // State variables for the thermostat
    reg [1:0] temp_state;
    reg heater_on;
    reg aircon_on;
    reg fan_on_state;

    // Assign initial state
    temp_state = LOW_TEMP;
    heater_on = 0;
    aircon_on = 0;
    fan_on_state = 0;

    // State machine logic for the thermostat
    always @(posedge mode or posedge too_cold or posedge too_hot or posedge fan_on) begin
        if (mode == 1) begin
            // Heating mode
            if (too_cold == 1) begin
                temp_state = HIGH_TEMP;
                heater_on = 1;
                aircon_on = 0;
            end else begin
                if (aircon_on == 1) begin
                    temp_state = HIGH_TEMP;
                    heater_on = 0;
                    aircon_on = 0;
                end else begin
                    temp_state = LOW_TEMP;
                    heater_on = 0;
                    aircon_on = 0;
                end
            end
        end else if (mode == 0) begin
            // Cooling mode
            if (too_hot == 1) begin
                temp_state = LOW_TEMP;
                heater_on = 0;
                aircon_on = 1;
            end else begin
                if (heater_on == 1) begin
                    temp_state = LOW_TEMP;
                    heater_on = 0;
                    aircon_on = 0;
                end else begin
                    temp_state = HIGH_TEMP;
                    heater_on = 0;
                    aircon_on = 0;
                end
            end
        end else begin
            // Fan on regardless of mode
            if (fan_on == 1) begin
                fan_on_state = 1;
            end else begin
                fan_on_state = 0;
            end
        end

        // Update outputs based on the state machine
        heater <= heater_on;
        aircon <= aircon_on;
        fan <= fan_on_state;
    end

endmodule

