reg [1:0] ab;
reg [1:0] cd;
reg [1:0] out_map [4:0];

always @(*) begin
    // Map the Karnaugh map to the output
    case (ab)
        2'b00: cd = 2'b00;
        2'b01: cd = 2'b01;
        2'b11: cd = 2'b11;
        2'b10: cd = 2'b10;
        default: cd = 2'b00; // Default to 0 for invalid input combinations
    endcase

    // Map the CD output to the final output
    case (cd)
        2'b00: out_map[0] = 1'b1; // CD 00 -> out 1
        2'b01: out_map[1] = 1'b0; // CD 01 -> out 0
        2'b11: out_map[2] = 1'b1; // CD 11 -> out 1
        2'b10: out_map[3] = 1'b0; // CD 10 -> out 0
        default: out_map[4] = 1'b0; // Default to 0 for invalid input combinations
    endcase

    out = out_map[a && b && (c || d)];
end

