  // Define the process to handle the shift register
  always @(posedge clk) begin
    if (E == 1'b1) begin
      // Shift the register left by one
      shift_reg <= shift_reg << 1;
    end
    if (L == 1'b1) begin
      // Load the register with the value from w
      shift_reg <= {w, shift_reg[6:0]};
    end
  end

  // Output the current value of the shift register
  assign Q = shift_reg[0];

endmodule

