module TopModule(
    input wire mode,
    input wire too_cold,
    input wire too_hot,
    input wire fan_on,
    output wire heater,
    output wire aircon,
    output wire fan
);

    // Constants for temperature states
    localparam LOW_TEMP = 0;
    localparam HIGH_TEMP = 1;

    // State variables for the thermostat
    reg [1:0] thermostat_state;

    // Main logic to control the heating/cooling and fan based on mode and temperature
    always @(posedge clock or posedge reset) begin
        if (reset) begin
            thermostat_state <= LOW_TEMP;
            heater <= 0;
            aircon <= 0;
            fan <= 0;
        end else begin
            case (thermostat_state)
                LOW_TEMP:
                    begin
                        heater <= (too_cold && !aircon);
                        aircon <= 0;
                        fan <= fan_on;
                    end
                HIGH_TEMP:
                    begin
                        heater <= 0;
                        aircon <= (too_hot && !heater);
                        fan <= fan_on;
                    end
            endcase

            // Update the state based on fan_on input
            if (fan_on) begin
                thermostat_state <= thermostat_state; // Fan is always active
            end else begin
                if (too_cold) begin
                    thermostat_state <= LOW_TEMP;
                end else if (too_hot) begin
                    thermostat_state <= HIGH_TEMP;
                end
            end
        end
    end

