module TopModule (
    input clk,
    input areset,
    input [7:0] d,
    output [7:0] q
);

    // 8 D flip-flops with active high asynchronous reset
    reg [7:0] dff[7:0];

    // Reset all DFFs to 0
    initial begin
        for (int i = 0; i < 8; i = i + 1) begin
            dff[i] <= 8'b0;
        end
    end

    // Trigger DFFs on positive edge of clk
    always @(posedge clk) begin
        for (int i = 0; i < 8; i = i + 1) begin
            if (areset == 1'b1) begin
                dff[i] <= 8'b0;
            end else if (d[i] != 8'b0) begin
                dff[i] <= d[i];
            end
        end
    end

    // Output should be reset to 0
    always @(posedge clk) begin
        q <= 8'b0;
    end

endmodule

