);

// Counter to track the 4-digit BCD
reg [3:0] count = 0;

// Enable signal to indicate when each digit should be incremented
reg [2:0] enable = 3'b111;

// Main process to update the counter and enable signals
always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 0;
        enable <= 3'b111;
