    output logic heater,
    output logic aircon,
    output logic fan
);

    // Variables for the thermostat state
    logic [1:0] thermostat_state = 2'b00; // 00 = not ready, 01 = heating, 10 = cooling

    // Logic to determine the thermostat state
    always @(mode or too_cold or too_hot or fan_on) begin
        if (mode == 1 && !too_cold) begin
            thermostat_state = 2'b01; // Heating
        end else if (mode == 0 && too_hot) begin
            thermostat_state = 2'b10; // Cooling
        end else begin
            thermostat_state = 2'b00; // Not ready
        end
    end

    // Logic to control the heater, air conditioner, and fan based on the thermostat state
    always @(thermostat_state or fan_on) begin
        if (thermostat_state == 2'b01) begin
            heater = 1'b1;
            aircon = 1'b0;
            fan = 1'b1;
        end else if (thermostat_state == 2'b10) begin
            heater = 1'b0;
            aircon = 1'b1;
            fan = 1'b1;
        end else begin
            heater = 1'b0;
            aircon = 1'b0;
            fan = 1'b0;
        end
    end

