module TopModule (
    input  in,
    input  state (4 bits),
    output next_state (4 bits),
    output out
);

// Define the one-hot state encoding
wire [3:0] state_one_hot;

// Map state inputs to one-hot encoding
always @(*) begin
    case (state)
        4'b0001: state_one_hot = 4'b0001;
        4'b0010: state_one_hot = 4'b0010;
        4'b0100: state_one_hot = 4'b0100;
        4'b1000: state_one_hot = 4'b1000;
        default: state_one_hot = 4'b0000; // Default state if input is invalid
    endcase
end

// Define the state transition logic and output logic equations
always @(posedge in or posedge state_one_hot) begin
    case (state_one_hot)
        4'b0001:
            next_state = state_one_hot;
            out = state_one_hot[0]; // Output the least significant bit of the next state
            break;
        4'b0010:
            next_state = state_one_hot;
            out = state_one_hot[1]; // Output the second least significant bit of the next state
            break;
        4'b0100:
            next_state = state_one_hot;
            out = state_one_hot[2]; // Output the third least significant bit of the next state
            break;
        4'b1000:
            next_state = state_one_hot;
            out = state_one_hot[3]; // Output the most significant bit of the next state
            break;
    endcase
end

endmodule

