module TopModule (
    input wire a,
    input wire b,
    input wire cin,
    output reg cout,
    output reg sum
);

    // Logic for the full adder
    reg reg_1, reg_2, reg_3, reg_4;
    reg reg_5, reg_6, reg_7;

    // Calculate the sum
    always @(*) begin
        reg_1 = a & b;
        reg_2 = reg_1 & cin;
        reg_3 = cin & reg_1;
        reg_4 = cin & cin;
        reg_5 = reg_2 | reg_3;
        reg_6 = reg_5 | reg_4;
        reg_7 = reg_5 | reg_4;
        sum = reg_6 | reg_7;
    end

    // Calculate the carry-out
    always @(*) begin
        reg_1 = a | b;
        reg_2 = reg_1 & cin;
        reg_3 = cin & reg_1;
        reg_4 = cin & cin;
        reg_5 = reg_2 | reg_3;
        reg_6 = reg_5 | reg_4;
        reg_7 = reg_5 | reg_4;
        cout = reg_6 | reg_7;
    end

endmodule

