    input  b,
    input  c,
    input  d,
    input  e,
    output reg [24:0] out
);

reg [24:0] comparison;

always @(*) begin
    // Initialize comparison register with initial value
    comparison = 25'b0;

    // Compare each pair of bits and set the appropriate bits in comparison register
    for (int i = 0; i < 5; i++) begin
        for (int j = i + 1; j < 5; j++) begin
            comparison = comparison | ~a[i] ^ a[j] | ~b[i] ^ b[j] | ~c[i] ^ c[j] | ~d[i] ^ d[j] | ~e[i] ^ e[j];
        end
    end
end

assign out = comparison;

endmodule

