localparam [3:0] A = 4'b0001, B = 4'b0010, C = 4'b0100, D = 4'b1000;

// Define the state transitions based on the input
always @(posedge in) begin
    case (state)
        A: begin
            next_state = state;
            out <= 0;
        end
        B: begin
            next_state = state;
            out <= 0;
        end
        C: begin
            next_state = D;
            out <= 0;
        end
        D: begin
            next_state = C;
            out <= 1;
        end
        default: begin
            next_state = state;
            out <= 0;
        end
    endcase
end

