module TopModule (
    input clk,
    input reset,
    output [2:0] ena,
    output [15:0] q
);

    // 4-digit BCD counter
    reg [3:0] tens;
    reg [3:0] ones;
    reg [3:0] hunds;
    reg [3:0] thousands;

    // Enable signals for each digit
    reg [2:0] ena_tens;
    reg [2:0] ena_ones;
    reg [2:0] ena_hunds;
    reg [2:0] ena_thousands;

    // Counter logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tens <= 0;
            ones <= 0;
            hunds <= 0;
            thousands <= 0;
            ena_tens <= 0;
            ena_ones <= 0;
            ena_hunds <= 0;
            ena_thousands <= 0;
        end else begin
            tens <= tens + 1'b1;
            if (tens == 0) begin
                ena_tens <= ~ena_tens;
            end
            if (tens == 9) begin
                ena_tens <= ena_tens;
            end

            ones <= ones + 1'b1;
            if (ones == 0) begin
                ena_ones <= ~ena_ones;
            end
            if (ones == 9) begin
                ena_ones <= ena_ones;
            end

            hunds <= hunds + 1'b1;
            if (hunds == 0) begin
                ena_hunds <= ~ena_hunds;
            end
            if (hunds == 9) begin
                ena_hunds <= ena_hunds;
            end

            thousands <= thousands + 1'b1;
            if (thousands == 0) begin
                ena_thousands <= ~ena_thousands;
            end
            if (thousands == 9) begin
                ena_thousands <= ena_thousands;
            end

            q[15:12] <= tens;
            q[11:8] <= ones;
            q[7:4] <= hunds;
            q[3:0] <= thousands;
        end
    end

    // Enable signals output
    assign ena = {ena_tens, ena_ones, ena_hunds, ena_thousands};

    // Output signal output
    assign q = {thousands, hunds, ones, tens};

endmodule

