    reg [7:0] popCount = 0;

    // Increment popCount each time a '1' is detected in the input
    always @(posedge in)
        if (in[0])
            popCount[7] <= popCount[6] ? popCount[6] + 1 : popCount[6];

        for (integer i = 1; i < 256; i++)
            if (in[i])
                popCount[i - 1] <= popCount[i - 2] ? popCount[i - 2] + 1 : popCount[i - 2];

