module TopModule (
    input clk,
    input w,
    input R,
    input E,
    input L,
    output Q
);

    // Declare a register to hold the current state of the shift register
    reg [7:0] shift_register;

    // Assign the initial value of the shift register
    initial begin
        shift_register = 8'b00000000;
    end

    // Implement the shift register logic
    always @(posedge clk) begin
        if (E) begin
            // Load the value from R into the shift register
            shift_register <= R;
        end else if (L) begin
            // Load the value from w into the shift register
            shift_register <= w;
        end else if (R) begin
            // Shift the register to the left by one bit
            shift_register <= {shift_register[6:0], 1'b0};
        end else if (w) begin
            // Shift the register to the right by one bit
            shift_register <= {1'b0, shift_register[7:1]};
        end
    end

    // Output the current state of the shift register
    assign Q = shift_register[7];

endmodule

