module TopModule (
    input wire mode,
    input wire too_cold,
    input wire too_hot,
    input wire fan_on,
    output reg heater,
    output reg aircon,
    output reg fan
);

// Define constants for heater and aircon modes
parameter HEATER_MODE = 1'b0;
parameter AIRCON_MODE = 1'b1;

// Define constants for heater and aircon control signals
parameter HEATER_ON = 1'b1;
parameter HEATER_OFF = 1'b0;
parameter AIRCON_ON = 1'b1;
parameter AIRCON_OFF = 1'b0;

// Define constants for fan control signal
parameter FAN_ON = 1'b1;
parameter FAN_OFF = 1'b0;

// Control signals for heater and aircon based on mode and inputs
reg heater_control = mode & too_cold;
reg aircon_control = mode & too_hot;

// Logic to control heater and aircon based on control signals
always @(posedge clk or posedge rst) begin
    if (rst) begin
        heater <= HEATER_OFF;
        aircon <= AIRCON_OFF;
        fan <= FAN_OFF;
    end else begin
        if (heater_control == HEATER_ON) begin
            heater <= HEATER_ON;
            aircon <= AIRCON_OFF;
            fan <= FAN_ON;
        end else if (aircon_control == AIRCON_ON) begin
            heater <= HEATER_OFF;
            aircon <= AIRCON_ON;
            fan <= FAN_ON;
        end else begin
            heater <= HEATER_OFF;
            aircon <= AIRCON_OFF;
            fan <= FAN_OFF;
        end
    end
end

// Logic to control fan based on fan_on input
always @(posedge clk or posedge rst) begin
    if (rst) begin
        fan <= FAN_OFF;
    end else begin
        if (fan_on) begin
            fan <= FAN_ON;
        end else begin
            fan <= FAN_OFF;
        end
    end
end

endmodule

