module TopModule (
    input wire in,
    input wire [3:0] state,
    output reg [3:0] next_state,
    output reg out
);

    // Declare state transition and output logic variables
    reg [3:0] transition;
    reg output_logic;

    // Define state transition logic
    always @(posedge in) begin
        case (state)
            4'b0001: transition = 4'b0010; // From A to B on input 0
            4'b0010: transition = 4'b0100; // From B to C on input 0
            4'b0100: transition = 4'b0001; // From C to A on input 0
            4'b1000: transition = 4'b0100; // From D to C on input 0
            default: transition = state; // Stay in the same state on other inputs
        endcase
    end

    // Define output logic
    always @(*) begin
        case (transition)
            4'b0001: output_logic = 1'b0; // Output 0 on transition from A to B
            4'b0010: output_logic = 1'b0; // Output 0 on transition from B to C
            4'b0100: output_logic = 1'b0; // Output 0 on transition from C to A
            4'b1000: output_logic = 1'b1; // Output 1 on transition from D to C
            default: output_logic = 1'b0; // Output 0 on any other transition
        endcase
    end

    // Assign the transition to next_state and output logic to out
    assign next_state = transition;
    assign out = output_logic;

endmodule

