module population_counter #(parameter WIDTH=255) (
    input  wire [WIDTH-1:0] in,
    output wire [7:0] out
);

    wire [WIDTH-1:0] sum [8:0];  // Sum of the bits

    generate
        for (genvar i = 0; i < WIDTH; i++) begin: generate_sum
            sum[i] = in[i];
        end
