module TopModule (
    input clk,
    input w,
    input R,
    input E,
    input L,
    output Q
);

reg [7:0] shiftRegister = 0; // Initialize the 8-bit shift register

always @(posedge clk) begin
    if (E) begin
        if (R) begin
            // Load the input value into the shift register
            shiftRegister[0] = w;
        end else if (L) begin
            // Load the previous value into the shift register
            shiftRegister[7] = shiftRegister[6];
            // Shift the remaining bits to the left
            for (int i = 6; i >= 0; i--) begin
                shiftRegister[i] = shiftRegister[i - 1];
            end
        end else begin
            // Shift the remaining bits to the left
            for (int i = 6; i >= 0; i--) begin
                shiftRegister[i] = shiftRegister[i - 1];
            end
        end
    end
    Q <= shiftRegister[0]; // Output the least significant bit of the shift register

end

endmodule

