module XNOR #(parameter DELAY = 1)(input bit in1, input bit in2, output bit out);
  // Create a temporary buffer to hold the result of the XNOR gate
  logic tmp;

  // Perform the XNOR operation
  assign tmp = in1 ^ in2;

  // Delay the output of the XNOR gate
  delay gate_delay_inst(
    .clk in1,
    .en in1,
    .delay(DELAY),
    .out(out)
  );

  // Assign the final output
  assign out = tmp;
endmodule

module XOR #(parameter DELAY = 1)(input bit in1, input bit in2, output bit out);
  // Perform the XOR operation
  assign out = in1 ^ in2;
endmodule

module delay #(parameter DELAY = 1)(input logic clk, input logic en, input logic data, output logic delayed_data);
  // Create a counter to track the delay time
  reg [DELAY-1:0] count;
  reg [DELAY-1:0] clk_divider;
  wire [DELAY-1:0] clk_counter;

  // Instantiate a counter to track the delay time
  always @(posedge clk) begin
    clk_divider <= clk_divider + 1;
  end

  // Instantiate a counter to track the delay time
  always @(posedge clk_divider) begin
    count <= count + 1;
  end

  // Instantiate a wire to hold the delayed data
  always @(posedge count) begin
    delayed_data <= data;
  end
endmodule

