module population_counter_255 (
    input wire [255:0] in,
    output wire [7:0] out
);

    // Logic to count the number of '1's in the input vector
    reg [7:0] count;

    // Iterate through each bit of the input vector and count the '1's
    for (genvar i = 0; i < 256; i = i + 1) begin
        always @(posedge in[i]) begin
            if (in[i] == 1'b1) begin
                count = count + 1;
            end
        end
    end

    // Output the total count of '1's
    assign out = count;

